    ($SATQ$0d6ab461$SATQ$, $SATQ$df1e58e8-b763-42a1-a3e2-b70a4bac09d5$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Algebra$SATQ$, $SATQ$H$SATQ$, $SATQ$H.B.$SATQ$, $SATQ$Linear functions$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, NULL, $SATQ$<p style="text-align: left;">Gabriella deposits <math alttext="dollar sign 35"><mo>$</mo><mn>35</mn></math> in a savings account at the end of each week. At the beginning of the <math alttext="1st"><mn>1</mn><mtext>st</mtext></math> week of a year there was <math alttext="dollar sign 600"><mo>$</mo><mn>600</mn></math> in that savings account. How much money, in dollars, will be in the account at the end of the <math alttext="4th"><mn>4</mn><mtext>th</mtext></math> week of that year?</p>$SATQ$, $SATQ$[{"id":"3d521da2-6fcd-4924-a47b-c11f55c7bf12","content":"<p><math alttext=\"460\"><mn>460</mn>\n</math></p>"},{"id":"f4325c79-9afd-46fd-bfdb-0faf6453fdba","content":"<p><math alttext=\"635\"><mn>635</mn>\n</math></p>"},{"id":"fc13aa3c-61b1-47b6-bc90-23b09c981bf0","content":"<p><math alttext=\"639\"><mn>639</mn>\n</math></p>"},{"id":"cbc9e288-7834-4a8a-81c0-ecb5189049eb","content":"<p><math alttext=\"740\"><mn>740</mn>\n</math></p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["cbc9e288-7834-4a8a-81c0-ecb5189049eb"]$SATQ$::jsonb, $SATQ$<p style="text-align: left;">Choice D is correct. It&rsquo;s given that at the beginning of the&nbsp;<math alttext="1st"><mn>1</mn><mtext>st</mtext></math> week of the year there was <math alttext="dollar sign 600"><mo>$</mo><mn>600</mn></math> in a savings account and Gabriella deposits <math alttext="dollar sign 35"><mo>$</mo><mn>35</mn></math> in that savings account at the end of each week. Therefore, the amount of money, in dollars, in the savings account at the end of the <math alttext="4th"><mn>4</mn><mtext>th</mtext></math> week of that year is <math alttext="600 plus 4 left parenthesis 35 right parenthesis"><mn>600</mn><mo>+</mo><mn>4</mn><mfenced><mn>35</mn></mfenced></math>, or <math alttext="740"><mn>740</mn>
</math>.</p>
<p style="text-align: left;">Choice A is incorrect. This is the amount of money, in dollars, that will be in the account at the end of the <math alttext="4th"><mn>4</mn><mtext>th</mtext></math> week if Gabriella withdraws, rather than deposits, <math alttext="dollar sign 35"><mo>$</mo><mn>35</mn></math> at the end of each week.</p>
<p style="text-align: left;">Choice B is incorrect. This is the amount of money, in dollars, that will be in the account at the end of the&nbsp;<math alttext="1st"><mn>1</mn><mtext>st</mtext></math> week, not the <math alttext="4th"><mn>4</mn><mtext>th</mtext></math> week.</p>
<p style="text-align: left;">Choice C is incorrect and may result from conceptual or calculation errors.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"0d6ab461","external_id":"df1e58e8-b763-42a1-a3e2-b70a4bac09d5","disclosed_item_id":null,"source":"qbank","vaultid":null,"uId":"02a67fe5-4d1c-43dc-9090-af77856cd973","program":"SAT","test_type":2,"test_type_desc":"Math","primary_class_cd":"H","domain":"Algebra","skill_cd":"H.B.","skill_desc":"Linear functions","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":null,"stem":"<p style=\"text-align: left;\">Gabriella deposits <math alttext=\"dollar sign 35\"><mo>$</mo><mn>35</mn></math> in a savings account at the end of each week. At the beginning of the <math alttext=\"1st\"><mn>1</mn><mtext>st</mtext></math> week of a year there was <math alttext=\"dollar sign 600\"><mo>$</mo><mn>600</mn></math> in that savings account. How much money, in dollars, will be in the account at the end of the <math alttext=\"4th\"><mn>4</mn><mtext>th</mtext></math> week of that year?</p>","answerOptions":[{"id":"3d521da2-6fcd-4924-a47b-c11f55c7bf12","content":"<p><math alttext=\"460\"><mn>460</mn>\n</math></p>"},{"id":"f4325c79-9afd-46fd-bfdb-0faf6453fdba","content":"<p><math alttext=\"635\"><mn>635</mn>\n</math></p>"},{"id":"fc13aa3c-61b1-47b6-bc90-23b09c981bf0","content":"<p><math alttext=\"639\"><mn>639</mn>\n</math></p>"},{"id":"cbc9e288-7834-4a8a-81c0-ecb5189049eb","content":"<p><math alttext=\"740\"><mn>740</mn>\n</math></p>"}],"keys":["cbc9e288-7834-4a8a-81c0-ecb5189049eb"],"correct_answer":["D"],"rationale":"<p style=\"text-align: left;\">Choice D is correct. It&rsquo;s given that at the beginning of the&nbsp;<math alttext=\"1st\"><mn>1</mn><mtext>st</mtext></math> week of the year there was <math alttext=\"dollar sign 600\"><mo>$</mo><mn>600</mn></math> in a savings account and Gabriella deposits <math alttext=\"dollar sign 35\"><mo>$</mo><mn>35</mn></math> in that savings ac